AND a.management_no = #{criteria.managementNo}
AND u.login_id ILIKE CONCAT('%', #{criteria.teacherName}, '%')
AND a.management_item_code = #{criteria.managementItemCode}
AND a.achievement_status = #{criteria.achievementStatus}
AND ( FALSE
OR a.teacher_user_id = #{userId}
OR EXISTS ( SELECT 1 FROM organization_user_mappings r JOIN organization_user_mappings t ON t.organization_code = r.organization_code WHERE r.user_id = #{userId} AND r.status = 'ACTIVE' AND t.user_id = a.teacher_user_id AND t.status = 'ACTIVE' )
OR EXISTS ( SELECT 1 FROM evaluation_organization_mappings p JOIN organization_user_mappings t ON t.organization_code = p.organization_code WHERE p.user_id = #{userId} AND p.business_type = 'FACULTY_ACHIEVEMENT' AND p.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL') AND t.user_id = a.teacher_user_id AND t.status = 'ACTIVE' )
)

