INSERT INTO education_achievements (
    achievement_type, management_no, teacher_user_id, organization_code,
    evaluation_year, management_item_code, achievement_date, achievement_detail,
    attachment_ref, created_by, updated_by, request_id
)
VALUES (
    'FR-030', #{managementNo}, #{teacherUserId}, #{organizationCode},
    #{evaluationYear}, #{managementItemCode}, #{achievementDate}, #{performanceDetails},
    #{attachmentRef}, #{teacherUserId}, #{teacherUserId}, #{requestId}
)

INSERT INTO course_operation_achievement_details (
    achievement_id, performance_detail, created_by, updated_by
)
VALUES (
    #{achievementId}, #{performanceDetails}, #{teacherUserId}, #{teacherUserId}
)

INSERT INTO education_achievement_status_histories (
    achievement_type, achievement_id, next_status, action_type, opinion, processed_by, request_id
)
